def get_odd_collatz(n):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def collatz_sequence(x):
        seq = [x]
        while x != 1:
            if x % 2 == 0:
                x = x // 2
            else:
                x = 3 * x + 1
            seq.append(x)
        return seq

    sequence = collatz_sequence(n)
    odd_numbers = [num for num in sequence if num % 2 == 1]
    return sorted(set(odd_numbers))
