def valid_date(date):
    """Validate if the given date string is in the format mm-dd-yyyy and meets date rules."""
    if not date:
        return False

    # Check if the format is mm-dd-yyyy
    pattern = r'^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])-\d{4}$'
    match = re.match(pattern, date)
    if not match:
        return False

    month_str, day_str, year_str = match.groups()
    month = int(month_str)
    day = int(day_str)
    year = int(year_str)

    # Validate month
    if month < 1 or month > 12:
        return False

    # Determine max days in month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        max_day = 31
    elif month in [4, 6, 9, 11]:
        max_day = 30
    elif month == 2:
        # Simplistic leap year check
        if (year % 400 == 0) or (year % 4 == 0 and year % 100 != 0):
            max_day = 29
        else:
            max_day = 28
    else:
        return False

    # Validate day
    if day < 1 or day > max_day:
        return False

    return True
