def minPath(grid, k):
    """
    Finds the lexicographically minimal path of length k in the grid.
    """
    N = len(grid)
    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    # Initialize the DP array: for each cell, store the lex minimal path of length l ending at that cell
    # path_dp[(r,c)] = list of length k representing the path
    path_dp = [[None for _ in range(N)] for _ in range(N)]

    # For paths of length 1, the path is just the cell value
    for r in range(N):
        for c in range(N):
            path_dp[r][c] = [grid[r][c]]

    # For each length from 2 to k
    for length in range(2, k + 1):
        new_dp = [[None for _ in range(N)] for _ in range(N)]
        for r in range(N):
            for c in range(N):
                candidates = []
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        prev_path = path_dp[nr][nc]
                        if prev_path is not None:
                            candidate_path = prev_path + [grid[r][c]]
                            candidates.append(candidate_path)
                if candidates:
                    # Select the lex minimal path among candidates
                    new_dp[r][c] = min(candidates)
        path_dp = new_dp

