def minPath(grid, k):
    N = len(grid)
    # Map each value to its position for quick access
    value_positions = {}
    for i in range(N):
        for j in range(N):
            value_positions[grid[i][j]] = (i, j)
    # Directions for neighbors: up, down, left, right
    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    # Initialize DP array: for each cell, store a list of paths
    # Each path is represented as a list of values
    # For k=1, initialize with the starting cell's value
    # Use a structure: dp[cell] = list of minimal paths ending at cell
    # For memory considerations, since paths are lexicographically comparable,
    # we can keep only the minimal path per cell for each path length
    # But since we need to compare lex order of entire path, we must keep track of the minimal paths
    # For each cell and length, keep only the lex smallest path
    # To do this efficiently, use a dictionary: dp[(i, j, length)] = minimal path list

    # Initialize for paths of length 1
    from collections import defaultdict
    dp = {}
    for i in range(N):
        for j in range(N):
            dp[(i, j, 1)] = [grid[i][j]]

    for length in range(2, k+1):
        new_dp = {}
        for (i, j, l), path in dp.items():
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < N and 0 <= nj < N:
                    candidate_path = path + [grid[ni][nj]]
                    key = (ni, nj, length)
                    if key not in new_dp:
                        new_dp[key] = candidate_path
                    else:
                        # Keep only lex smaller
                        if candidate_path < new_dp[key]:
                            new_dp[key] = candidate_path
        dp = new_dp

    # Now find the minimal path among all ending positions for length k
    min_path = None
    for key, path in dp.items():
        if len(path) == k:
            if min_path is None or path < min_path:
                min_path = path
    return min_path
